#!/usr/bin/env python3
"""Entry program for "Saturday 21 November 2026" (news-image-20261121).

Running this file writes the finished poster to ./entry.png.
The poster was designed as HTML/CSS and rendered to PNG with headless
Chrome (see README.md); the PNG bytes are embedded below as base64 so
this program is fully self-contained.
"""

import base64
import hashlib
import os
import sys
import tempfile

_PNG_B64 = ""
EXPECTED_SHA256 = "d495fc90af4ee4309d9578d34a293336e4cabf1d9f3d53ab5ef004948d586757"


def main():
    data = base64.b64decode(_PNG_B64)
    digest = hashlib.sha256(data).hexdigest()
    if digest != EXPECTED_SHA256:
        print("checksum mismatch: decoded data is corrupt", file=sys.stderr)
        return 1
    dest = os.environ.get("MAKEFUN_OUTPUT_DIR") or os.getcwd()
    out = os.path.join(dest, "entry.png")
    # Atomic, self-verifying copy: write to a temp file in the same
    # directory, verify what landed on disk, then os.replace() so a
    # reader never sees a partial entry.png.
    fd, tmp = tempfile.mkstemp(dir=dest, prefix=".entry-", suffix=".tmp")
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        with open(tmp, "rb") as f:
            on_disk = hashlib.sha256(f.read()).hexdigest()
        if on_disk != EXPECTED_SHA256:
            print("checksum mismatch: write did not survive intact", file=sys.stderr)
            return 1
        os.replace(tmp, out)
        # mkstemp creates the temp file mode 0600 and os.replace keeps
        # that mode; make the landed artifact world-readable so the
        # scorer (a different uid) can read entry.png.
        os.chmod(out, 0o644)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise
    print("wrote", out, len(data), "bytes, sha256", digest)
    return 0


if __name__ == "__main__":
    sys.exit(main())
